module.exports = [
{ e: "🍋", art: { b: "⚓", s: ["🍋", "🐀", "🍞", "🌊"], c: ["#5A4A1B", "#F0E07A"] },
pt: { h: "Leo perguntou o que os marinheiros comiam nas viagens longas. O vovô fez uma careta: “Biscoito duro, cheio de bichinhos, carne salgada e água meio estragada! E muitos ficavam com uma doença terrível chamada escorbuto. Sabe o que curava? Algo que você tem na fruteira!” Leo olhou e pegou um limão: “Isso?” “Exatamente!”", t: "A vida a bordo e o mistério do escorbuto", f: "Nos navios antigos, a vida era muito difícil. Os marinheiros dormiam apertados, enfrentavam tempestades e trabalhavam dia e noite. A comida precisava durar meses, por isso era seca ou salgada, sem frutas e verduras frescas. Sem vitamina C, muitos marinheiros pegavam escorbuto: as gengivas sangravam, os dentes caíam, e eles ficavam muito fracos. Em algumas viagens, morreram mais marinheiros de escorbuto do que de tempestades.", x: "Em 1747, o médico escocês James Lind fez um dos primeiros experimentos científicos controlados da história: deu alimentos diferentes para grupos de marinheiros doentes e descobriu que os que comiam laranjas e limões melhoravam rapidamente! Anos depois, os navios ingleses passaram a levar suco de limão, e os marinheiros britânicos ganharam o apelido de “limeys”.", s: ["Os ratos eram passageiros clandestinos em quase todos os navios.", "O biscoito de bordo era tão duro que às vezes precisava ser molhado para conseguir comer.", "Hoje sabemos que a vitamina C está em frutas como laranja, acerola, goiaba e kiwi."], at: "Rota nº 11", m: "Diário de Bordo, lápis de cor, frutas cítricas", p: ["Monte um cardápio de bordo com alimentos que durariam meses sem estragar.", "Desenhe o experimento de James Lind, com os marinheiros comendo coisas diferentes.", "Faça uma lista de frutas com vitamina C que você levaria na sua viagem."], q: "Que comida você mais sentiria falta numa viagem de meses no mar?" },
en: { h: "Leo asked what sailors ate on long voyages. Grandpa made a face: “Hard biscuits full of little bugs, salted meat and half-spoiled water! And many got a terrible disease called scurvy. Do you know what cured it? Something in your fruit bowl!” Leo looked and picked up a lemon: “This?” “Exactly!”", t: "Life on board and the mystery of scurvy", f: "Life on old sailing ships was very hard. Sailors slept crammed together, faced storms and worked day and night. Food had to last for months, so it was dried or salted, without fresh fruit and vegetables. Without vitamin C, many sailors got scurvy: their gums bled, their teeth fell out and they became very weak. On some voyages, more sailors died of scurvy than of storms.", x: "In 1747, Scottish doctor James Lind ran one of the first controlled scientific experiments in history: he gave different foods to groups of sick sailors and discovered that those who ate oranges and lemons got better quickly! Years later, British ships began carrying citrus juice, and British sailors got the nickname “limeys.”", s: ["Rats were stowaways on almost every ship.", "Ship's biscuit was so hard that sometimes it had to be soaked before it could be eaten.", "Today we know vitamin C is found in fruits like oranges, acerola, guava and kiwi."], at: "Route no. 11", m: "your Logbook, colored pencils, citrus fruit", p: ["Plan a ship's menu with foods that would last months without spoiling.", "Draw James Lind's experiment, with sailors eating different things.", "Make a list of vitamin C fruits you'd bring on your voyage."], q: "Which food would you miss most on a months-long voyage at sea?" },
es: { h: "Leo preguntó qué comían los marineros en los viajes largos. El abuelo hizo una mueca: “¡Galleta dura, llena de bichitos, carne salada y agua medio podrida! Y muchos se enfermaban de una enfermedad terrible llamada escorbuto. ¿Sabes qué la curaba? ¡Algo que tienes en la frutera!” Leo miró y agarró un limón: “¿Esto?” “¡Exacto!”", t: "La vida a bordo y el misterio del escorbuto", f: "En los barcos antiguos, la vida era muy difícil. Los marineros dormían apretados, enfrentaban tormentas y trabajaban día y noche. La comida tenía que durar meses, por eso era seca o salada, sin frutas ni verduras frescas. Sin vitamina C, muchos marineros se enfermaban de escorbuto: les sangraban las encías, se les caían los dientes y quedaban muy débiles. En algunos viajes murieron más marineros de escorbuto que por las tormentas.", x: "¡En 1747, el médico escocés James Lind hizo uno de los primeros experimentos científicos controlados de la historia: les dio alimentos distintos a grupos de marineros enfermos y descubrió que los que comían naranjas y limones mejoraban rápidamente! Años después, los barcos ingleses empezaron a llevar jugo de limón, y a los marineros británicos los apodaron “limeys”.", s: ["Las ratas eran pasajeras clandestinas en casi todos los barcos.", "La galleta de a bordo era tan dura que a veces había que mojarla para poder comerla.", "Hoy sabemos que la vitamina C está en frutas como la naranja, la mandarina, la guayaba y el kiwi."], at: "Ruta nº 11", m: "Diario de a Bordo, lápices de colores, frutas cítricas", p: ["Arma un menú de a bordo con alimentos que durarían meses sin echarse a perder.", "Dibuja el experimento de James Lind, con los marineros comiendo cosas distintas.", "Haz una lista de frutas con vitamina C que llevarías en tu viaje."], q: "¿Qué comida extrañarías más en un viaje de meses en el mar?" } },

{ e: "🗺️", art: { b: "🗺️", s: ["🌍", "🍊", "📏", "🖊️"], c: ["#1B4A5A", "#F0A03A"] },
pt: { h: "Nina comparou um globo terrestre com um mapa-múndi pendurado na parede e ficou confusa: “No mapa, a Groenlândia parece do tamanho da África inteira, mas no globo ela é bem menor! Qual está certo?” O vovô riu: “O globo! Achatar uma bola num papel sempre estica alguma coisa. Os cartógrafos inventaram muitos jeitos de fazer isso.”", t: "Os mapas e os cartógrafos", f: "Os cartógrafos são as pessoas que desenham mapas. Com as informações trazidas pelos exploradores, os mapas foram ficando cada vez mais completos. Mas existe um problema: a Terra é redonda e o papel é plano. Para transformar o globo num mapa, é preciso esticar ou cortar algumas partes, e por isso todo mapa-múndi tem algum tipo de distorção. Esses diferentes jeitos de desenhar o mundo se chamam projeções.", x: "Em 1569, o cartógrafo flamengo Gerardus Mercator criou um mapa muito útil para navegar, porque as linhas retas nele mostravam as direções da bússola. Mas, nesse mapa, os lugares perto dos polos ficam enormes: a Groenlândia parece do tamanho da África, quando, na verdade, a África é cerca de 14 vezes maior!", s: ["O mapa mais antigo do mundo que conhecemos é uma tabuinha de argila da Babilônia.", "Hoje, os mapas são feitos com fotos de satélites e aviões.", "O Brasil é o quinto maior país do mundo em área."], ex: { t: "A casca de laranja que vira mapa", m: "uma laranja, uma caneta, uma faca (usada por um adulto)", p: ["Desenhe na casca da laranja os continentes, como se fosse um globo.", "Com um adulto, faça cortes do topo até embaixo e tire a casca inteira com cuidado.", "Tente deixar a casca totalmente plana na mesa: ela rasga ou deixa espaços vazios! É o mesmo problema dos cartógrafos ao fazer mapas."] }, at: "Rota nº 12", m: "Diário de Bordo, lápis de cor, um mapa-múndi e um globo (se tiver)", p: ["Compare o tamanho da Groenlândia e da África no mapa e no globo.", "Desenhe o mapa do caminho da sua casa até a escola, com legenda.", "Invente um mapa de um país imaginário, com montanhas, rios e cidades."], q: "Se você fosse cartógrafo, que lugar gostaria de colocar no mapa pela primeira vez?" },
en: { h: "Nina compared a globe with a world map hanging on the wall and got confused: “On the map, Greenland looks as big as all of Africa, but on the globe it's much smaller! Which one is right?” Grandpa laughed: “The globe! Flattening a ball onto paper always stretches something. Mapmakers invented lots of ways to do it.”", t: "Maps and mapmakers", f: "Cartographers are the people who draw maps. With information brought back by explorers, maps became more and more complete. But there's a problem: Earth is round and paper is flat. To turn the globe into a map, you have to stretch or cut some parts, so every world map has some kind of distortion. These different ways of drawing the world are called projections.", x: "In 1569, Flemish cartographer Gerardus Mercator created a map that was very useful for navigating, because straight lines on it showed compass directions. But on that map, places near the poles look enormous: Greenland looks as big as Africa, when actually Africa is about 14 times bigger!", s: ["The oldest known world map is a clay tablet from Babylon.", "Today maps are made with photos from satellites and planes.", "Brazil is the fifth-largest country in the world by area."], ex: { t: "Orange peel map", m: "an orange, a pen, a knife (used by a grown-up)", p: ["Draw the continents on the orange peel as if it were a globe.", "With a grown-up, make cuts from top to bottom and carefully remove the whole peel.", "Try to lay the peel completely flat on the table: it tears or leaves gaps! That's the same problem mapmakers face."] }, at: "Route no. 12", m: "your Logbook, colored pencils, a world map and a globe (if you have them)", p: ["Compare the size of Greenland and Africa on the map and on the globe.", "Draw a map of the route from your home to school, with a key.", "Invent a map of an imaginary country, with mountains, rivers and cities."], q: "If you were a cartographer, what place would you like to put on the map for the first time?" },
es: { h: "Nina comparó un globo terráqueo con un planisferio colgado en la pared y se confundió: “En el mapa, Groenlandia parece del tamaño de toda África, ¡pero en el globo es mucho más chica! ¿Cuál está bien?” El abuelo se rió: “¡El globo! Aplanar una pelota en un papel siempre estira algo. Los cartógrafos inventaron muchas formas de hacerlo.”", t: "Los mapas y los cartógrafos", f: "Los cartógrafos son las personas que dibujan mapas. Con la información que traían los exploradores, los mapas se fueron volviendo cada vez más completos. Pero hay un problema: la Tierra es redonda y el papel es plano. Para convertir el globo en un mapa hay que estirar o cortar algunas partes, y por eso todo planisferio tiene algún tipo de distorsión. Esas distintas formas de dibujar el mundo se llaman proyecciones.", x: "¡En 1569, el cartógrafo flamenco Gerardus Mercator creó un mapa muy útil para navegar, porque las líneas rectas en él mostraban las direcciones de la brújula! Pero, en ese mapa, los lugares cerca de los polos quedan enormes: Groenlandia parece del tamaño de África, cuando en realidad África es unas 14 veces más grande.", s: ["El mapa del mundo más antiguo que conocemos es una tablilla de arcilla de Babilonia.", "Hoy los mapas se hacen con fotos de satélites y aviones.", "Argentina es el octavo país más grande del mundo en superficie."], ex: { t: "La cáscara de naranja que se vuelve mapa", m: "una naranja, una lapicera, un cuchillo (usado por un adulto)", p: ["Dibuja en la cáscara de la naranja los continentes, como si fuera un globo.", "Con un adulto, haz cortes de arriba abajo y saca la cáscara entera con cuidado.", "Intenta dejar la cáscara totalmente plana en la mesa: ¡se rompe o deja espacios vacíos! Es el mismo problema de los cartógrafos al hacer mapas."] }, at: "Ruta nº 12", m: "Diario de a Bordo, lápices de colores, un planisferio y un globo (si tienes)", p: ["Compara el tamaño de Groenlandia y de África en el mapa y en el globo.", "Dibuja el mapa del camino de tu casa a la escuela, con referencias.", "Inventa un mapa de un país imaginario, con montañas, ríos y ciudades."], q: "Si fueras cartógrafo, ¿qué lugar te gustaría poner en el mapa por primera vez?" } },

{ e: "📡", art: { b: "🌳", s: ["📡", "🐴", "🤝", "🗺️"], c: ["#1B5A2A", "#F0C83A"] },
pt: { h: "No mapa do Brasil, Leo encontrou um estado chamado Rondônia. “Por que esse nome?”, perguntou. “É uma homenagem a um grande explorador brasileiro, o Marechal Rondon”, explicou o vovô. “Ele atravessou florestas e rios do interior do Brasil e tinha um lema muito bonito: ‘Morrer, se preciso for; matar, nunca’.”", t: "Rondon, o explorador do sertão", f: "Cândido Rondon nasceu em 1865, no Mato Grosso, e tinha antepassados indígenas. No começo dos anos 1900, ele liderou expedições para levar linhas de telégrafo pelo interior do Brasil, atravessando milhares de quilômetros de florestas, rios e campos ainda pouco conhecidos pelos governos. Nas viagens, ele fez mapas, estudou plantas e animais e conheceu muitos povos indígenas, sempre procurando um contato pacífico.", x: "Em 1913 e 1914, Rondon guiou o ex-presidente americano Theodore Roosevelt numa expedição perigosa pelo Rio da Dúvida, na Amazônia, que depois foi rebatizado de Rio Roosevelt! Rondon também ajudou a criar o primeiro órgão de proteção aos indígenas do Brasil e foi indicado ao Prêmio Nobel da Paz.", s: ["Rondon e sua equipe registraram muitas espécies de plantas e animais desconhecidas pelos cientistas da época.", "O telégrafo mandava mensagens por fios usando código Morse.", "Rondon defendia que os povos indígenas tinham direito às suas terras."], at: "Rota nº 13", m: "Diário de Bordo, lápis de cor, um mapa do Brasil", p: ["No mapa do Brasil, encontre o estado de Rondônia e o Rio Roosevelt.", "Desenhe a expedição de Rondon atravessando um rio da floresta com os postes de telégrafo.", "Escreva o que você acha que significa o lema “Morrer, se preciso for; matar, nunca”."], q: "Por que você acha que é importante explorar com respeito pelos povos que vivem nos lugares?" },
en: { h: "On a map of Brazil, Leo found a state called Rondônia. “Why that name?” he asked. “It honors a great Brazilian explorer, Marshal Rondon,” Grandpa explained. “He crossed forests and rivers in Brazil's interior and had a beautiful motto: ‘Die if necessary; kill, never.’”", t: "Rondon, explorer of the interior", f: "Cândido Rondon was born in 1865 in Mato Grosso, Brazil, and had Indigenous ancestors. In the early 1900s, he led expeditions to string telegraph lines across Brazil's interior, crossing thousands of kilometers of forests, rivers and grasslands that the government knew little about. On his journeys, he made maps, studied plants and animals and met many Indigenous peoples, always seeking peaceful contact.", x: "In 1913 and 1914, Rondon guided former U.S. president Theodore Roosevelt on a dangerous expedition down the River of Doubt in the Amazon, which was later renamed the Roosevelt River! Rondon also helped create Brazil's first agency to protect Indigenous peoples and was nominated for the Nobel Peace Prize.", s: ["Rondon and his team recorded many plant and animal species unknown to scientists of the time.", "The telegraph sent messages over wires using Morse code.", "Rondon argued that Indigenous peoples had the right to their lands."], at: "Route no. 13", m: "your Logbook, colored pencils, a map of Brazil", p: ["On a map of Brazil, find the state of Rondônia and the Roosevelt River.", "Draw Rondon's expedition crossing a forest river with telegraph poles.", "Write what you think the motto “Die if necessary; kill, never” means."], q: "Why do you think it's important to explore with respect for the peoples who live in a place?" },
es: { h: "En el mapa de Brasil, Leo encontró un estado llamado Rondônia. “¿Por qué ese nombre?”, preguntó. “Es un homenaje a un gran explorador brasileño, el mariscal Rondon”, explicó el abuelo. “Atravesó selvas y ríos del interior de Brasil y tenía un lema muy lindo: ‘Morir, si es necesario; matar, nunca’.”", t: "Rondon, el explorador del interior", f: "Cândido Rondon nació en 1865, en Mato Grosso, Brasil, y tenía antepasados indígenas. A principios de los años 1900, lideró expediciones para llevar líneas de telégrafo por el interior de Brasil, atravesando miles de kilómetros de selvas, ríos y campos todavía poco conocidos por los gobiernos. En los viajes hizo mapas, estudió plantas y animales y conoció a muchos pueblos indígenas, buscando siempre un contacto pacífico.", x: "¡En 1913 y 1914, Rondon guió al expresidente estadounidense Theodore Roosevelt en una expedición peligrosa por el Río de la Duda, en la Amazonia, que después pasó a llamarse río Roosevelt! Rondon también ayudó a crear el primer organismo de protección de los indígenas de Brasil y fue propuesto para el Premio Nobel de la Paz.", s: ["Rondon y su equipo registraron muchas especies de plantas y animales desconocidas para los científicos de la época.", "El telégrafo mandaba mensajes por cables usando código Morse.", "Rondon defendía que los pueblos indígenas tenían derecho a sus tierras."], at: "Ruta nº 13", m: "Diario de a Bordo, lápices de colores, un mapa de Brasil", p: ["En el mapa de Brasil, encuentra el estado de Rondônia y el río Roosevelt.", "Dibuja la expedición de Rondon cruzando un río de la selva con los postes de telégrafo.", "Escribe qué crees que significa el lema “Morir, si es necesario; matar, nunca”."], q: "¿Por qué crees que es importante explorar con respeto por los pueblos que viven en cada lugar?" } },

{ e: "🛶", art: { b: "🛶", s: ["🌳", "🏹", "🤝", "🏡"], c: ["#2A5A2A", "#F0A03A"] },
pt: { h: "Nina viu fotos de três irmãos de chapéu e barba, sentados numa canoa, conversando com pessoas indígenas na beira de um rio. “Quem são eles?”, perguntou. “Os irmãos Villas-Bôas: Orlando, Cláudio e Leonardo”, disse o vovô. “Eles exploraram o Brasil Central e lutaram para proteger os povos indígenas do Xingu.”", t: "Os irmãos Villas-Bôas e o Xingu", f: "Nos anos 1940, o governo brasileiro organizou uma grande expedição, chamada Roncador-Xingu, para abrir caminhos e conhecer o centro do país. Os irmãos Villas-Bôas participaram dela e, durante décadas, atravessaram florestas e rios, abrindo pistas de pouso e fazendo mapas. No caminho, conheceram muitos povos indígenas e perceberam que eles precisavam de proteção para continuar vivendo em suas terras, do seu jeito.", x: "Graças à luta dos irmãos Villas-Bôas e de lideranças indígenas, foi criado em 1961 o Parque Indígena do Xingu, uma das primeiras grandes terras indígenas do Brasil! Lá vivem hoje vários povos diferentes, com suas línguas, festas e tradições, como o Kuarup, uma grande cerimônia em homenagem aos mortos.", s: ["O Parque do Xingu fica no Mato Grosso e é cortado pelo Rio Xingu.", "Na expedição, os irmãos fundaram vilas que depois viraram cidades.", "Os povos do Xingu são conhecidos pela pintura corporal, pelas danças e pela luta huka-huka."], at: "Rota nº 14", m: "Diário de Bordo, lápis de cor, um mapa do Brasil", p: ["No mapa, encontre o Rio Xingu e o estado do Mato Grosso.", "Desenhe uma canoa descendo o rio, com a floresta dos dois lados.", "Escreva 3 coisas que um bom explorador deveria fazer ao chegar a uma aldeia."], q: "Como você se comportaria se fosse visitar um povo com costumes diferentes dos seus?" },
en: { h: "Nina saw photos of three bearded brothers in hats sitting in a canoe, talking with Indigenous people on a riverbank. “Who are they?” she asked. “The Villas-Bôas brothers: Orlando, Cláudio and Leonardo,” said Grandpa. “They explored central Brazil and fought to protect the Indigenous peoples of the Xingu.”", t: "The Villas-Bôas brothers and the Xingu", f: "In the 1940s, the Brazilian government organized a big expedition called Roncador-Xingu to open routes and get to know the center of the country. The Villas-Bôas brothers took part and, for decades, crossed forests and rivers, clearing airstrips and making maps. Along the way, they met many Indigenous peoples and realized they needed protection to keep living on their lands in their own way.", x: "Thanks to the efforts of the Villas-Bôas brothers and Indigenous leaders, the Xingu Indigenous Park was created in 1961, one of Brazil's first large Indigenous territories! Several different peoples live there today, with their own languages, festivals and traditions, like the Kuarup, a great ceremony honoring the dead.", s: ["The Xingu Park is in Mato Grosso and is crossed by the Xingu River.", "During the expedition, the brothers founded settlements that later became towns.", "The peoples of the Xingu are known for body painting, dances and huka-huka wrestling."], at: "Route no. 14", m: "your Logbook, colored pencils, a map of Brazil", p: ["On the map, find the Xingu River and the state of Mato Grosso.", "Draw a canoe going down the river with forest on both sides.", "Write 3 things a good explorer should do when arriving at a village."], q: "How would you behave if you visited a people with customs different from yours?" },
es: { h: "Nina vio fotos de tres hermanos de sombrero y barba, sentados en una canoa, conversando con personas indígenas a la orilla de un río. “¿Quiénes son?”, preguntó. “Los hermanos Villas-Bôas: Orlando, Cláudio y Leonardo”, dijo el abuelo. “Exploraron el centro de Brasil y lucharon para proteger a los pueblos indígenas del Xingú.”", t: "Los hermanos Villas-Bôas y el Xingú", f: "En los años 1940, el gobierno brasileño organizó una gran expedición, llamada Roncador-Xingú, para abrir caminos y conocer el centro del país. Los hermanos Villas-Bôas participaron y, durante décadas, atravesaron selvas y ríos, abriendo pistas de aterrizaje y haciendo mapas. En el camino conocieron a muchos pueblos indígenas y se dieron cuenta de que necesitaban protección para seguir viviendo en sus tierras, a su manera.", x: "¡Gracias a la lucha de los hermanos Villas-Bôas y de líderes indígenas, en 1961 se creó el Parque Indígena del Xingú, una de las primeras grandes tierras indígenas de Brasil! Allí viven hoy varios pueblos distintos, con sus lenguas, fiestas y tradiciones, como el Kuarup, una gran ceremonia en homenaje a los muertos.", s: ["El Parque del Xingú está en Mato Grosso y lo atraviesa el río Xingú.", "En la expedición, los hermanos fundaron poblados que después se convirtieron en ciudades.", "Los pueblos del Xingú son conocidos por la pintura corporal, las danzas y la lucha huka-huka."], at: "Ruta nº 14", m: "Diario de a Bordo, lápices de colores, un mapa de Brasil", p: ["En el mapa, encuentra el río Xingú y el estado de Mato Grosso.", "Dibuja una canoa bajando por el río, con la selva de los dos lados.", "Escribe 3 cosas que debería hacer un buen explorador al llegar a una aldea."], q: "¿Cómo te comportarías si fueras a visitar a un pueblo con costumbres distintas de las tuyas?" } },

{ e: "🐂", art: { b: "🛶", s: ["🏔️", "👶", "🗺️", "🐻"], c: ["#5A3A1B", "#F0C83A"] },
pt: { h: "Leo viu uma moeda americana dourada com o desenho de uma mulher carregando um bebê nas costas. “Quem é ela?”, perguntou. “É Sacagawea”, respondeu o vovô. “Uma jovem indígena do povo Shoshone que ajudou dois exploradores a atravessar os Estados Unidos, com o filho bebê nas costas o caminho todo!”", t: "Lewis, Clark e Sacagawea", f: "Em 1804, Meriwether Lewis e William Clark partiram numa grande expedição para atravessar a América do Norte até o Oceano Pacífico, fazendo mapas e estudando plantas e animais. Na viagem, eles conheceram Sacagawea, uma jovem indígena Shoshone. Ela ajudou como tradutora, encontrou plantas para comer e mostrou que a expedição vinha em paz, porque nenhum grupo de guerra viajaria com uma mulher e um bebê.", x: "Numa das partes mais difíceis da viagem, a expedição precisava de cavalos para atravessar as montanhas, e encontraram justamente o povo Shoshone. O chefe era o irmão de Sacagawea, que ela não via desde criança! Graças a esse reencontro emocionante, eles conseguiram os cavalos. A viagem toda durou mais de dois anos.", s: ["A expedição descreveu cerca de 200 plantas e animais novos para os cientistas da época.", "O bebê de Sacagawea, Jean Baptiste, ganhou o apelido de “Pompy”.", "A expedição contou com a ajuda de muitos povos indígenas no caminho."], at: "Rota nº 15", m: "Diário de Bordo, lápis de cor, um mapa da América do Norte", p: ["No mapa, trace a rota de Lewis e Clark, do meio dos Estados Unidos até o Oceano Pacífico.", "Desenhe Sacagawea guiando a expedição com o bebê nas costas.", "Desenhe 3 animais novos que você acha que eles encontraram, como o urso-pardo e o bisão."], q: "Por que você acha que os guias locais eram tão importantes para os exploradores?" },
en: { h: "Leo saw a gold-colored U.S. coin with a picture of a woman carrying a baby on her back. “Who is she?” he asked. “That's Sacagawea,” Grandpa answered. “A young Shoshone woman who helped two explorers cross the United States, carrying her baby on her back the whole way!”", t: "Lewis, Clark and Sacagawea", f: "In 1804, Meriwether Lewis and William Clark set out on a great expedition to cross North America to the Pacific Ocean, making maps and studying plants and animals. On the journey, they met Sacagawea, a young Shoshone woman. She helped as an interpreter, found plants to eat and showed that the expedition came in peace, because no war party would travel with a woman and a baby.", x: "During one of the hardest parts of the journey, the expedition needed horses to cross the mountains, and they met none other than the Shoshone people. Their chief turned out to be Sacagawea's brother, whom she hadn't seen since she was a child! Thanks to this emotional reunion, they got the horses. The whole journey took more than two years.", s: ["The expedition described about 200 plants and animals new to scientists of the time.", "Sacagawea's baby, Jean Baptiste, was nicknamed “Pomp.”", "The expedition relied on help from many Indigenous peoples along the way."], at: "Route no. 15", m: "your Logbook, colored pencils, a map of North America", p: ["On the map, trace Lewis and Clark's route from the middle of the United States to the Pacific Ocean.", "Draw Sacagawea guiding the expedition with her baby on her back.", "Draw 3 new animals you think they met, like the grizzly bear and the bison."], q: "Why do you think local guides were so important to explorers?" },
es: { h: "Leo vio una moneda estadounidense dorada con el dibujo de una mujer cargando a un bebé en la espalda. “¿Quién es?”, preguntó. “Es Sacagawea”, respondió el abuelo. “¡Una joven indígena del pueblo shoshone que ayudó a dos exploradores a cruzar Estados Unidos, con su hijo bebé en la espalda todo el camino!”", t: "Lewis, Clark y Sacagawea", f: "En 1804, Meriwether Lewis y William Clark partieron en una gran expedición para cruzar América del Norte hasta el océano Pacífico, haciendo mapas y estudiando plantas y animales. En el viaje conocieron a Sacagawea, una joven indígena shoshone. Ella ayudó como traductora, encontró plantas para comer y mostró que la expedición venía en paz, porque ningún grupo de guerra viajaría con una mujer y un bebé.", x: "¡En una de las partes más difíciles del viaje, la expedición necesitaba caballos para cruzar las montañas, y justo se encontraron con el pueblo shoshone! El jefe era el hermano de Sacagawea, a quien ella no veía desde chica. Gracias a ese reencuentro emocionante, consiguieron los caballos. Todo el viaje duró más de dos años.", s: ["La expedición describió unas 200 plantas y animales nuevos para los científicos de la época.", "Al bebé de Sacagawea, Jean Baptiste, lo apodaron “Pomp”.", "La expedición contó con la ayuda de muchos pueblos indígenas en el camino."], at: "Ruta nº 15", m: "Diario de a Bordo, lápices de colores, un mapa de América del Norte", p: ["En el mapa, traza la ruta de Lewis y Clark, del centro de Estados Unidos hasta el océano Pacífico.", "Dibuja a Sacagawea guiando la expedición con el bebé en la espalda.", "Dibuja 3 animales nuevos que crees que encontraron, como el oso pardo y el bisonte."], q: "¿Por qué crees que los guías locales eran tan importantes para los exploradores?" } },

{ e: "🎒", art: { b: "🎒", s: ["🌍", "👒", "🦋", "📔"], c: ["#6B1B4A", "#F0A0C2"] },
pt: { h: "Nina leu sobre uma senhora austríaca que, há quase 180 anos, decidiu dar a volta ao mundo sozinha, com pouca bagagem e pouco dinheiro. “Naquela época as mulheres podiam viajar sozinhas?”, perguntou. “Era muito raro!”, disse o vovô. “Mas Ida Pfeiffer não deixou ninguém dizer que ela não podia.”", t: "Ida Pfeiffer, a viajante corajosa", f: "Ida Pfeiffer nasceu em Viena, na Áustria, em 1797. Desde criança sonhava em viajar, mas só conseguiu realizar o sonho depois de criar os filhos. Com mais de 40 anos, ela partiu sozinha e deu duas voltas ao mundo, visitando a América do Sul, inclusive o Brasil, a Ásia, a África e ilhas do Pacífico. Ela viajava de forma simples, coletava plantas, insetos e minerais para museus e escrevia livros sobre suas aventuras.", x: "Os livros de Ida Pfeiffer foram traduzidos para vários idiomas e fizeram muito sucesso! Com o dinheiro dos livros, ela pagava as próximas viagens. Ela foi uma das primeiras mulheres aceitas como membro em sociedades de geografia da Europa, numa época em que quase só homens podiam participar.", s: ["No Brasil, Ida Pfeiffer visitou o Rio de Janeiro e a floresta, nos anos 1840.", "Ela viajava com uma mochila pequena e gastava muito pouco.", "Muitas das coleções dela ainda estão em museus."], at: "Rota nº 16", m: "Diário de Bordo, lápis de cor, uma mochila pequena", p: ["Faça a mochila de viagem de Ida Pfeiffer: escolha só 10 coisas para uma viagem de um ano.", "Desenhe Ida coletando borboletas e plantas numa floresta.", "Escreva uma página do diário de uma viajante que chegou a um país novo."], q: "Que sonho você gostaria de realizar, mesmo que alguém dissesse que é difícil?" },
en: { h: "Nina read about an Austrian woman who, almost 180 years ago, decided to travel around the world on her own, with little luggage and little money. “Could women travel alone back then?” she asked. “It was very rare!” said Grandpa. “But Ida Pfeiffer didn't let anyone tell her she couldn't.”", t: "Ida Pfeiffer, the brave traveler", f: "Ida Pfeiffer was born in Vienna, Austria, in 1797. From childhood she dreamed of traveling, but she could only make that dream come true after raising her children. In her forties, she set out alone and traveled around the world twice, visiting South America, including Brazil, Asia, Africa and Pacific islands. She traveled simply, collected plants, insects and minerals for museums and wrote books about her adventures.", x: "Ida Pfeiffer's books were translated into several languages and were very successful! She used the money from her books to pay for her next trips. She was one of the first women accepted as a member of geographical societies in Europe, at a time when almost only men could join.", s: ["In Brazil, Ida Pfeiffer visited Rio de Janeiro and the rainforest in the 1840s.", "She traveled with a small backpack and spent very little.", "Many of her collections are still in museums."], at: "Route no. 16", m: "your Logbook, colored pencils, a small backpack", p: ["Pack Ida Pfeiffer's travel bag: choose just 10 things for a year-long trip.", "Draw Ida collecting butterflies and plants in a forest.", "Write a diary page of a traveler arriving in a new country."], q: "What dream would you like to make come true, even if someone said it was hard?" },
es: { h: "Nina leyó sobre una señora austríaca que, hace casi 180 años, decidió dar la vuelta al mundo sola, con poco equipaje y poco dinero. “¿En esa época las mujeres podían viajar solas?”, preguntó. “¡Era muy raro!”, dijo el abuelo. “Pero Ida Pfeiffer no dejó que nadie le dijera que no podía.”", t: "Ida Pfeiffer, la viajera valiente", f: "Ida Pfeiffer nació en Viena, Austria, en 1797. Desde chica soñaba con viajar, pero recién pudo cumplir su sueño después de criar a sus hijos. Con más de 40 años, partió sola y dio dos vueltas al mundo, visitando América del Sur, incluido Brasil, Asia, África e islas del Pacífico. Viajaba de forma simple, recolectaba plantas, insectos y minerales para museos y escribía libros sobre sus aventuras.", x: "¡Los libros de Ida Pfeiffer se tradujeron a varios idiomas y tuvieron mucho éxito! Con el dinero de los libros, pagaba sus siguientes viajes. Fue una de las primeras mujeres aceptadas como miembro en sociedades de geografía de Europa, en una época en que casi solo podían participar los hombres.", s: ["En Brasil, Ida Pfeiffer visitó Río de Janeiro y la selva, en los años 1840.", "Viajaba con una mochila chica y gastaba muy poco.", "Muchas de sus colecciones siguen en museos."], at: "Ruta nº 16", m: "Diario de a Bordo, lápices de colores, una mochila chica", p: ["Arma la mochila de viaje de Ida Pfeiffer: elige solo 10 cosas para un viaje de un año.", "Dibuja a Ida recolectando mariposas y plantas en una selva.", "Escribe una página del diario de una viajera que llegó a un país nuevo."], q: "¿Qué sueño te gustaría cumplir, aunque alguien te dijera que es difícil?" } },

{ e: "🐧", art: { b: "🐧", s: ["🐕", "🛷", "❄️", "🚩"], c: ["#1B3A6B", "#E0F0FF"] },
pt: { h: "Leo vestiu três casacos, luvas e gorro, só de brincadeira, e reclamou: “Que calor!” O vovô riu: “Imagina usar tudo isso num lugar onde faz mais de 30 graus abaixo de zero! Foi o que fizeram os exploradores que disputaram uma corrida para chegar ao ponto mais ao sul da Terra: o Polo Sul.”", t: "A corrida ao Polo Sul", f: "A Antártida é o continente mais frio, mais seco e com mais vento da Terra, quase todo coberto por uma camada de gelo de quilômetros de espessura. No começo dos anos 1900, duas equipes disputaram quem chegaria primeiro ao Polo Sul: a do norueguês Roald Amundsen e a do inglês Robert Scott. Amundsen usou trenós puxados por cães, esquis e roupas inspiradas nos povos do Ártico, e chegou primeiro, em 14 de dezembro de 1911.", x: "Scott e sua equipe chegaram ao Polo Sul cerca de cinco semanas depois e encontraram a barraca e a bandeira deixadas por Amundsen. Infelizmente, no caminho de volta, enfrentaram um frio terrível e não sobreviveram. Amundsen tinha aprendido muito com os povos Inuit sobre como viver no frio, e isso fez toda a diferença.", s: ["No inverno da Antártida, o Sol pode passar meses sem aparecer.", "Hoje existem estações científicas de vários países na Antártida, inclusive do Brasil.", "Os pinguins-imperadores vivem na Antártida e aguentam o inverno mais gelado do planeta."], at: "Rota nº 17", m: "Diário de Bordo, lápis de cor, gelo, luvas", p: ["Segure um cubo de gelo com a mão sem luva e depois com luva: compare quanto tempo aguenta.", "Desenhe a equipe de Amundsen com os trenós e os cães chegando ao Polo Sul.", "Faça uma lista do que você levaria para uma expedição na Antártida."], q: "O que você acha que foi mais difícil para os exploradores da Antártida?" },
en: { h: "Leo put on three coats, gloves and a hat, just for fun, and complained: “It's so hot!” Grandpa laughed: “Imagine wearing all that in a place where it's more than 30 degrees below zero! That's what the explorers did who raced to reach the southernmost point on Earth: the South Pole.”", t: "The race to the South Pole", f: "Antarctica is the coldest, driest and windiest continent on Earth, almost entirely covered by an ice sheet kilometers thick. In the early 1900s, two teams competed to be the first to reach the South Pole: one led by Norwegian Roald Amundsen and one by Englishman Robert Scott. Amundsen used sleds pulled by dogs, skis and clothing inspired by Arctic peoples, and he got there first, on December 14, 1911.", x: "Scott and his team reached the South Pole about five weeks later and found the tent and flag Amundsen had left. Sadly, on the way back, they faced terrible cold and didn't survive. Amundsen had learned a lot from the Inuit about living in the cold, and that made all the difference.", s: ["In the Antarctic winter, the Sun can stay hidden for months.", "Today several countries, including Brazil, have research stations in Antarctica.", "Emperor penguins live in Antarctica and survive the coldest winter on the planet."], at: "Route no. 17", m: "your Logbook, colored pencils, ice, gloves", p: ["Hold an ice cube in your bare hand and then with a glove: compare how long you can last.", "Draw Amundsen's team with their sleds and dogs arriving at the South Pole.", "Make a list of what you'd bring on an Antarctic expedition."], q: "What do you think was hardest for the Antarctic explorers?" },
es: { h: "Leo se puso tres camperas, guantes y gorro, solo para jugar, y se quejó: “¡Qué calor!” El abuelo se rió: “¡Imagínate usar todo eso en un lugar donde hace más de 30 grados bajo cero! Eso hicieron los exploradores que compitieron en una carrera para llegar al punto más al sur de la Tierra: el Polo Sur.”", t: "La carrera al Polo Sur", f: "La Antártida es el continente más frío, más seco y con más viento de la Tierra, casi todo cubierto por una capa de hielo de kilómetros de espesor. A principios de los años 1900, dos equipos compitieron para ver quién llegaba primero al Polo Sur: el del noruego Roald Amundsen y el del inglés Robert Scott. Amundsen usó trineos tirados por perros, esquíes y ropa inspirada en los pueblos del Ártico, y llegó primero, el 14 de diciembre de 1911.", x: "Scott y su equipo llegaron al Polo Sur unas cinco semanas después y encontraron la carpa y la bandera que había dejado Amundsen. Lamentablemente, en el camino de vuelta enfrentaron un frío terrible y no sobrevivieron. Amundsen había aprendido mucho de los pueblos inuit sobre cómo vivir en el frío, y eso hizo toda la diferencia.", s: ["En el invierno de la Antártida, el Sol puede pasar meses sin aparecer.", "Hoy hay bases científicas de varios países en la Antártida, como las de Argentina y Chile.", "Los pingüinos emperador viven en la Antártida y aguantan el invierno más helado del planeta."], at: "Ruta nº 17", m: "Diario de a Bordo, lápices de colores, hielo, guantes", p: ["Sostén un cubito de hielo con la mano sin guante y después con guante: compara cuánto tiempo aguantas.", "Dibuja al equipo de Amundsen con los trineos y los perros llegando al Polo Sur.", "Haz una lista de lo que llevarías a una expedición a la Antártida."], q: "¿Qué crees que fue lo más difícil para los exploradores de la Antártida?" } },

{ e: "🧊", art: { b: "🧊", s: ["🐧", "🛷", "🧭", "⭐"], c: ["#2A4A6B", "#C2E0F0"] },
pt: { h: "Nina viu uma foto antiga de um homem negro sorridente, vestido com roupas de pele, no meio do gelo do Ártico. “Quem é ele?”, perguntou. “É Matthew Henson”, contou o vovô. “Ele era um explorador americano muito habilidoso, que falava a língua dos Inuit, construía trenós e foi peça-chave numa das primeiras expedições ao Polo Norte.”", t: "Matthew Henson e o Polo Norte", f: "Diferente do Polo Sul, o Polo Norte não fica num continente: ele está no meio do Oceano Ártico, coberto por uma camada de gelo que flutua e se move. Em 1909, o americano Robert Peary e Matthew Henson, junto com quatro guias Inuit, Ootah, Egingwah, Seegloo e Ooqueah, afirmaram ter chegado ao Polo Norte. Henson era o membro mais experiente da equipe: sabia guiar os trenós de cães, caçar, consertar equipamentos e conversar com os Inuit.", x: "Por muitos anos, Matthew Henson não recebeu o reconhecimento que merecia, por causa do racismo da época. Só décadas depois ele passou a ser homenageado como um grande explorador, e hoje um navio de pesquisa da marinha americana tem o seu nome! Até hoje, os historiadores discutem se a equipe chegou exatamente ao ponto do Polo Norte ou um pouco antes.", s: ["Os Inuit vivem no Ártico há milhares de anos e sabem construir iglus com blocos de neve.", "No Polo Norte, todas as direções apontam para o sul!", "Os ursos-polares caçam focas no gelo do Ártico."], at: "Rota nº 18", m: "Diário de Bordo, lápis de cor, cubos de açúcar ou de gelo", p: ["Construa um miniglu com cubos de açúcar ou de gelo.", "Desenhe a equipe de Henson e dos guias Inuit atravessando o gelo com os trenós.", "Escreva por que é importante reconhecer todas as pessoas que ajudaram numa grande conquista."], q: "Quem você acha que merece mais reconhecimento por ajudar as pessoas à sua volta?" },
en: { h: "Nina saw an old photo of a smiling Black man dressed in fur clothing, out on the Arctic ice. “Who is he?” she asked. “That's Matthew Henson,” Grandpa told her. “He was a very skilled American explorer who spoke the Inuit language, built sleds and was key to one of the first expeditions to the North Pole.”", t: "Matthew Henson and the North Pole", f: "Unlike the South Pole, the North Pole isn't on a continent: it's in the middle of the Arctic Ocean, covered by a layer of ice that floats and drifts. In 1909, American Robert Peary and Matthew Henson, together with four Inuit guides, Ootah, Egingwah, Seegloo and Ooqueah, claimed to have reached the North Pole. Henson was the team's most experienced member: he knew how to drive dog sleds, hunt, repair equipment and talk with the Inuit.", x: "For many years, Matthew Henson didn't get the recognition he deserved because of the racism of the time. Only decades later did he begin to be honored as a great explorer, and today a U.S. Navy research ship bears his name! To this day, historians debate whether the team reached the exact North Pole or stopped a little short.", s: ["The Inuit have lived in the Arctic for thousands of years and know how to build igloos from snow blocks.", "At the North Pole, every direction points south!", "Polar bears hunt seals on the Arctic ice."], at: "Route no. 18", m: "your Logbook, colored pencils, sugar cubes or ice cubes", p: ["Build a mini igloo out of sugar cubes or ice cubes.", "Draw Henson's team and the Inuit guides crossing the ice with their sleds.", "Write why it's important to recognize everyone who helped with a great achievement."], q: "Who do you think deserves more recognition for helping the people around them?" },
es: { h: "Nina vio una foto antigua de un hombre negro sonriente, vestido con ropa de piel, en medio del hielo del Ártico. “¿Quién es?”, preguntó. “Es Matthew Henson”, contó el abuelo. “Era un explorador estadounidense muy hábil, que hablaba la lengua de los inuit, construía trineos y fue clave en una de las primeras expediciones al Polo Norte.”", t: "Matthew Henson y el Polo Norte", f: "A diferencia del Polo Sur, el Polo Norte no está en un continente: está en medio del océano Ártico, cubierto por una capa de hielo que flota y se mueve. En 1909, el estadounidense Robert Peary y Matthew Henson, junto con cuatro guías inuit, Ootah, Egingwah, Seegloo y Ooqueah, afirmaron haber llegado al Polo Norte. Henson era el miembro más experimentado del equipo: sabía guiar los trineos de perros, cazar, arreglar equipos y conversar con los inuit.", x: "¡Durante muchos años, Matthew Henson no recibió el reconocimiento que merecía, por el racismo de la época! Recién décadas después empezaron a homenajearlo como un gran explorador, y hoy un barco de investigación de la marina estadounidense lleva su nombre. Hasta hoy, los historiadores discuten si el equipo llegó exactamente al punto del Polo Norte o un poco antes.", s: ["Los inuit viven en el Ártico desde hace miles de años y saben construir iglúes con bloques de nieve.", "¡En el Polo Norte, todas las direcciones apuntan al sur!", "Los osos polares cazan focas sobre el hielo del Ártico."], at: "Ruta nº 18", m: "Diario de a Bordo, lápices de colores, terrones de azúcar o cubitos de hielo", p: ["Construye un miniiglú con terrones de azúcar o cubitos de hielo.", "Dibuja al equipo de Henson y los guías inuit cruzando el hielo con los trineos.", "Escribe por qué es importante reconocer a todas las personas que ayudaron en un gran logro."], q: "¿Quién crees que merece más reconocimiento por ayudar a las personas que lo rodean?" } },

{ e: "🚢", art: { b: "🚢", s: ["🧊", "🛶", "🐧", "💪"], c: ["#1B2A4A", "#A0C8F0"] },
pt: { h: "O vovô contou uma das histórias de sobrevivência mais incríveis de todos os tempos: “Um navio chamado Endurance ficou preso no gelo da Antártida por meses, até ser esmagado e afundar. A tripulação ficou sozinha no gelo, sem jeito de pedir ajuda.” Leo arregalou os olhos: “E o que aconteceu com eles?” “Todos sobreviveram!”", t: "Shackleton e o Endurance", f: "Em 1914, o explorador irlandês Ernest Shackleton partiu com 27 homens para atravessar a Antártida a pé. Mas o navio Endurance ficou preso no gelo e, depois de meses, foi esmagado e afundou. A tripulação acampou no gelo flutuante e depois navegou em botes salva-vidas até uma ilha deserta. Shackleton e alguns companheiros enfrentaram mais de 1.300 quilômetros de mar gelado e tempestuoso num pequeno bote para buscar ajuda.", x: "Depois de quase dois anos, Shackleton conseguiu resgatar todos os seus homens, sem perder nenhum! Ele ficou famoso por manter a equipe unida e esperançosa nos momentos mais difíceis. E, em 2022, mais de cem anos depois, cientistas encontraram o Endurance no fundo do mar da Antártida, a mais de 3 mil metros de profundidade, ainda muito bem conservado.", s: ["O nome Endurance quer dizer “resistência”.", "No fundo do mar gelado, quase não existem bichos que comem madeira, por isso o navio se conservou.", "A tripulação comeu focas e pinguins para sobreviver."], at: "Rota nº 19", m: "Diário de Bordo, lápis de cor, papel e um prato com água e gelo", p: ["Faça um barquinho de papel e coloque num prato com cubos de gelo em volta, como o Endurance preso.", "Desenhe a tripulação acampada no gelo, com os botes salva-vidas.", "Escreva 3 coisas que um bom líder faz para ajudar a equipe numa situação difícil."], q: "O que você faria para manter os amigos animados num momento difícil?" },
en: { h: "Grandpa told one of the most incredible survival stories of all time: “A ship called Endurance was trapped in Antarctic ice for months until it was crushed and sank. The crew was left alone on the ice, with no way to call for help.” Leo's eyes went wide: “What happened to them?” “They all survived!”", t: "Shackleton and the Endurance", f: "In 1914, Irish explorer Ernest Shackleton set out with 27 men to cross Antarctica on foot. But the ship Endurance got trapped in the ice and, after months, was crushed and sank. The crew camped on the floating ice and then sailed lifeboats to a deserted island. Shackleton and a few companions crossed more than 1,300 kilometers of icy, stormy sea in a small boat to get help.", x: "After almost two years, Shackleton managed to rescue all of his men without losing a single one! He became famous for keeping his team united and hopeful in the hardest moments. And in 2022, more than a hundred years later, scientists found the Endurance on the Antarctic seafloor, more than 3,000 meters deep and still remarkably well preserved.", s: ["The name Endurance means the ability to keep going through hardship.", "On the icy seafloor there are almost no creatures that eat wood, which is why the ship was preserved.", "The crew ate seals and penguins to survive."], at: "Route no. 19", m: "your Logbook, colored pencils, paper and a plate with water and ice", p: ["Make a paper boat and put it on a plate surrounded by ice cubes, like the trapped Endurance.", "Draw the crew camped on the ice with their lifeboats.", "Write 3 things a good leader does to help a team in a tough situation."], q: "What would you do to keep your friends' spirits up in a hard moment?" },
es: { h: "El abuelo contó una de las historias de supervivencia más increíbles de todos los tiempos: “Un barco llamado Endurance quedó atrapado en el hielo de la Antártida durante meses, hasta que fue aplastado y se hundió. La tripulación quedó sola en el hielo, sin forma de pedir ayuda.” Leo abrió grandes los ojos: “¿Y qué les pasó?” “¡Todos sobrevivieron!”", t: "Shackleton y el Endurance", f: "En 1914, el explorador irlandés Ernest Shackleton partió con 27 hombres para cruzar la Antártida a pie. Pero el barco Endurance quedó atrapado en el hielo y, después de meses, fue aplastado y se hundió. La tripulación acampó sobre el hielo flotante y después navegó en botes salvavidas hasta una isla desierta. Shackleton y algunos compañeros cruzaron más de 1.300 kilómetros de mar helado y tormentoso en un bote chico para buscar ayuda.", x: "¡Después de casi dos años, Shackleton logró rescatar a todos sus hombres, sin perder a ninguno! El rescate final se hizo con la ayuda de un barco chileno, el Yelcho. Shackleton se hizo famoso por mantener al equipo unido y con esperanza en los momentos más difíciles. Y, en 2022, más de cien años después, científicos encontraron el Endurance en el fondo del mar de la Antártida, a más de 3 mil metros de profundidad, todavía muy bien conservado.", s: ["El nombre Endurance quiere decir “resistencia”.", "En el fondo del mar helado casi no hay bichos que coman madera, por eso el barco se conservó.", "La tripulación comió focas y pingüinos para sobrevivir."], at: "Ruta nº 19", m: "Diario de a Bordo, lápices de colores, papel y un plato con agua y hielo", p: ["Haz un barquito de papel y ponlo en un plato con cubitos de hielo alrededor, como el Endurance atrapado.", "Dibuja a la tripulación acampando sobre el hielo, con los botes salvavidas.", "Escribe 3 cosas que hace un buen líder para ayudar al equipo en una situación difícil."], q: "¿Qué harías para mantener animados a tus amigos en un momento difícil?" } },

{ e: "🌊", art: { b: "🤿", s: ["🐙", "🐟", "🔦", "⬇️"], c: ["#0B1B3A", "#3A7AC2"] },
pt: { h: "Leo mergulhou na piscina e tentou chegar ao fundo, mas sentiu os ouvidos apertando. “Vovô, até onde as pessoas já conseguiram descer no mar?” O vovô sorriu: “Até o lugar mais fundo de todos, com quase 11 quilômetros de profundidade! Mas, para isso, foi preciso um submarino especial muito, muito resistente.”", t: "Explorando as profundezas do oceano", f: "O ponto mais fundo dos oceanos fica na Fossa das Marianas, no Oceano Pacífico, e se chama Abismo Challenger, com cerca de 11 quilômetros de profundidade. Lá embaixo, é totalmente escuro e muito frio, e a pressão da água é enorme: é como ter o peso de vários elefantes apertando cada pedacinho do tamanho de um selo. Mesmo assim, existem seres vivos lá, como pequenos crustáceos e peixes estranhos.", x: "Em 1960, Jacques Piccard e Don Walsh foram os primeiros a chegar ao fundo da Fossa das Marianas, a bordo de um submarino chamado Trieste. A viagem para descer levou quase 5 horas, e eles ficaram só uns 20 minutos lá embaixo! Hoje, poucas pessoas já foram até lá, menos do que as pessoas que já foram ao espaço.", s: ["Se o Monte Everest fosse colocado na Fossa das Marianas, o topo ainda ficaria debaixo d'água.", "Muitos peixes das profundezas produzem a própria luz.", "A maior parte do fundo do mar nunca foi vista de perto por ninguém."], ex: { t: "O mergulhador na garrafa", m: "uma garrafa PET de 2 litros com tampa, água, um conta-gotas ou um sachê de ketchup", p: ["Encha a garrafa com água até a boca.", "Coloque o conta-gotas com um pouco de água dentro (ou o sachê de ketchup), para que ele boie bem no topo, quase afundando. Feche bem a tampa.", "Aperte a garrafa com as mãos: o “mergulhador” desce até o fundo! Solte e ele sobe de novo. A pressão faz ele descer e subir, como um submarino."] }, at: "Rota nº 20", m: "Diário de Bordo, lápis de cor", p: ["Desenhe o oceano em camadas, da superfície ensolarada até o fundo escuro da Fossa das Marianas.", "Desenhe um peixe das profundezas inventado por você, com a sua própria luz.", "Desenhe o submarino Trieste descendo até o fundo do mar."], q: "Você preferiria explorar o fundo do mar ou o espaço? Por quê?" },
en: { h: "Leo dove into the pool and tried to touch the bottom, but felt his ears squeezing. “Grandpa, how deep have people ever gone in the sea?” Grandpa smiled: “All the way to the deepest place of all, almost 11 kilometers down! But that took a special, very, very strong submarine.”", t: "Exploring the ocean depths", f: "The deepest point in the oceans is in the Mariana Trench, in the Pacific Ocean, and it's called the Challenger Deep, about 11 kilometers deep. Down there it's completely dark and very cold, and the water pressure is enormous: it's like having the weight of several elephants pressing on every postage-stamp-sized spot. Even so, there are living things there, like tiny crustaceans and strange fish.", x: "In 1960, Jacques Piccard and Don Walsh were the first to reach the bottom of the Mariana Trench, aboard a submersible called Trieste. The trip down took almost 5 hours, and they spent only about 20 minutes at the bottom! Even today, fewer people have been there than have been to space.", s: ["If Mount Everest were placed in the Mariana Trench, its peak would still be underwater.", "Many deep-sea fish make their own light.", "Most of the seafloor has never been seen up close by anyone."], ex: { t: "Diver in a bottle", m: "a 2-liter plastic bottle with a cap, water, a dropper or a ketchup packet", p: ["Fill the bottle with water all the way to the top.", "Put in the dropper with a little water inside (or the ketchup packet), so it floats right at the top, almost sinking. Close the cap tightly.", "Squeeze the bottle with your hands: the “diver” sinks to the bottom! Let go and it rises again. Pressure makes it go down and up, like a submarine."] }, at: "Route no. 20", m: "your Logbook, colored pencils", p: ["Draw the ocean in layers, from the sunny surface to the dark bottom of the Mariana Trench.", "Draw a deep-sea fish you invent, with its own light.", "Draw the Trieste submersible descending to the bottom of the sea."], q: "Would you rather explore the bottom of the sea or space? Why?" },
es: { h: "Leo se tiró a la pileta e intentó llegar al fondo, pero sintió que se le apretaban los oídos. “Abuelo, ¿hasta dónde lograron bajar las personas en el mar?” El abuelo sonrió: “¡Hasta el lugar más profundo de todos, con casi 11 kilómetros de profundidad! Pero para eso hizo falta un submarino especial muy, muy resistente.”", t: "Explorando las profundidades del océano", f: "El punto más profundo de los océanos está en la fosa de las Marianas, en el océano Pacífico, y se llama abismo Challenger, con unos 11 kilómetros de profundidad. Allá abajo está totalmente oscuro y hace mucho frío, y la presión del agua es enorme: es como tener el peso de varios elefantes apretando cada pedacito del tamaño de una estampilla. Aun así, hay seres vivos allí, como pequeños crustáceos y peces extraños.", x: "¡En 1960, Jacques Piccard y Don Walsh fueron los primeros en llegar al fondo de la fosa de las Marianas, a bordo de un batiscafo llamado Trieste! El viaje para bajar duró casi 5 horas, y se quedaron solo unos 20 minutos allá abajo. Hoy, pocas personas fueron hasta allí, menos que las que fueron al espacio.", s: ["Si se pusiera el monte Everest en la fosa de las Marianas, la cima todavía quedaría debajo del agua.", "Muchos peces de las profundidades producen su propia luz.", "La mayor parte del fondo del mar nunca la vio nadie de cerca."], ex: { t: "El buzo en la botella", m: "una botella plástica de 2 litros con tapa, agua, un gotero o un sobrecito de kétchup", p: ["Llena la botella con agua hasta el borde.", "Mete el gotero con un poco de agua adentro (o el sobrecito de kétchup), para que flote justo arriba, casi hundiéndose. Cierra bien la tapa.", "Aprieta la botella con las manos: ¡el “buzo” baja hasta el fondo! Suelta y vuelve a subir. La presión lo hace bajar y subir, como un submarino."] }, at: "Ruta nº 20", m: "Diario de a Bordo, lápices de colores", p: ["Dibuja el océano en capas, desde la superficie soleada hasta el fondo oscuro de la fosa de las Marianas.", "Dibuja un pez de las profundidades inventado por ti, con su propia luz.", "Dibuja el batiscafo Trieste bajando hasta el fondo del mar."], q: "¿Preferirías explorar el fondo del mar o el espacio? ¿Por qué?" } },
];
